INSERT INTO faqs (question, answer, order_index) VALUES
('Quanto tempo demora um detalhe interior?', 'O Pack Básico demora cerca de 1h, enquanto o Premium pode ir até 2h, dependendo do estado da viatura.', 1),
('Fazem serviço ao domicílio?', 'Atualmente trabalhamos apenas nas nossas instalações em Leiria para garantirmos o ambiente controlado e a iluminação ideal para o detalhe.', 2),
('Que métodos de pagamento aceitam?', 'Aceitamos pagamentos por MB Way, Multibanco, numerário e cartões Visa/Mastercard no nosso estúdio.', 3),
('É preciso fazer marcação prévia?', 'Sim, trabalhamos exclusivamente por marcação para garantir que cada viatura tem o tempo e a dedicação necessários.', 4),
('Quanto tempo dura a proteção cerâmica?', 'Dependendo do tipo de revestimento e dos cuidados de manutenção, a proteção cerâmica pode durar entre 2 a 5 anos.', 5),
('Posso lavar o carro depois da proteção cerâmica?', 'Sim, mas recomendamos que utilize apenas produtos de pH neutro e evite lavagens automáticas com escovas.', 6);